const std = @import("std");

pub const SetupRequest = extern struct {
    byte_order: u8 = 'l',
    pad_1: u8 = 0,
    protocol_major_version: u16 = 11,
    protocol_minor_version: u16 = 0,
    authorization_protocol_name_len: u16 = 0,
    authorization_protocol_data_len: u16 = 0,
    pad_2: u16 = 0,
};

pub const ImageOrder = enum(u8) {
    LSBFirst = 0,
    MSBFirst = 1,
};

pub const FORMAT = extern struct {
    depth: u8,
    bits_per_pixel: u8,
    scanline_pad: u8,
    pad_1: [5]u8,
    pub fn format(
        self: @This(),
        writer: *std.Io.Writer,
    ) !void {
        const fields = @typeInfo(@This()).@"struct".fields;
        try writer.print("    Format.{{\n", .{});
        inline for (fields) |field| {
            const val = @field(self, field.name);
            try writer.print("      .{s} = {any},\n", .{ field.name, val });
        }
        try writer.print("    }}", .{});
    }
};

pub const EventMask = packed struct(u32) {
    KeyPress: u1 = 0,
    KeyRelease: u1 = 0,
    ButtonPress: u1 = 0,
    ButtonRelease: u1 = 0,
    EnterWindow: u1 = 0,
    LeaveWindow: u1 = 0,
    PointerMotion: u1 = 0,
    PointerMotionHint: u1 = 0,
    Button1Motion: u1 = 0,
    Button2Motion: u1 = 0,
    Button3Motion: u1 = 0,
    Button4Motion: u1 = 0,
    Button5Motion: u1 = 0,
    ButtonMotion: u1 = 0,
    KeymapState: u1 = 0,
    Exposure: u1 = 0,
    VisibilityChange: u1 = 0,
    StructureNotify: u1 = 0,
    ResizeRedirect: u1 = 0,
    SubstructureNotify: u1 = 0,
    SubstructureRedirect: u1 = 0,
    FocusChange: u1 = 0,
    PropertyChange: u1 = 0,
    ColorMapChange: u1 = 0,
    OwnerGrabButton: u1 = 0,
    _: u7 = 0,
};

pub const BackingStore = enum(u8) {
    NotUseful = 0,
    WhenMapped = 1,
    Always = 2,
};

pub const BOOL = enum(u8) {
    FALSE = 0,
    TRUE = 1,
};

pub const WINDOW = u32;
pub const SCREEN = extern struct {
    root: WINDOW,
    default_colormap: u32,
    white_pixel: u32,
    black_pixel: u32,
    current_input_masks: EventMask,
    width_in_pixels: u16,
    height_in_pixels: u16,
    width_in_millimeters: u16,
    height_in_millimeters: u16,
    min_installed_maps: u16,
    max_installed_maps: u16,
    root_visual: u32,
    backing_stores: BackingStore,
    save_unders: BOOL,
    root_depth: u8,
    allowed_depths_len: u8,
    const FixedSize: usize = @divExact(@bitSizeOf(@This()), 8);
    pub fn allowed_depths(self: *align(8) const @This()) []const DEPTH {
        const base: [*]const u8 = @ptrCast(self);
        const res: [*]const DEPTH = @ptrCast(@alignCast(base + FixedSize));
        return res[0..self.allowed_depths_len];
    }
    pub fn format(
        self: @This(),
        writer: *std.Io.Writer,
    ) !void {
        const fields = @typeInfo(@This()).@"struct".fields;
        try writer.print("    Screen.{{\n", .{});
        inline for (fields) |field| {
            const val = @field(self, field.name);
            try writer.print("      .{s} = {any},\n", .{ field.name, val });
        }
        try writer.print("    }}", .{});
    }
};

pub const DEPTH = extern struct {
    name: u8,
    pad_1: u8,
    visuals_len: u16,
    pad_2: u32,
    const FixedSize: usize = @divExact(@bitSizeOf(@This()), 8);
    pub fn visuals(self: *const @This()) []const VISUALTYPE {
        const base: [*]const u8 = @ptrCast(self);
        const res: [*]const VISUALTYPE = @ptrCast(@alignCast(base + FixedSize));
        return res[0..self.visuals_len];
    }
};

pub const VISUALTYPE = extern struct {
    visual_id: u32,
    class: VisualClass,
    bits_per_rgb_value: u8,
    colormap_entries: u16,
    red_mask: u32,
    green_mask: u32,
    blue_mask: u32,
    pad_1: u32,
};

pub const VisualClass = enum(u8) {
    StaticGray = 0,
    GrayScale = 1,
    StaticColor = 2,
    PseudoColor = 3,
    TrueColor = 4,
    DirectColor = 5,
};

pub const SetupReply = extern struct {
    status: u8 = 1,
    pad_1: u8,
    protocol_major_version: u16,
    protocol_minor_version: u16,
    length: u16,
    release_number: u32,
    resource_id_base: u32,
    resource_id_mask: u32,
    motion_buffer_size: u32,
    vendor_len: u16,
    maximum_request_length: u16,
    roots_len: u8,
    pixmap_formats_len: u8,
    image_byte_order: ImageOrder,
    bitmap_format_bit_order: ImageOrder,
    bitmap_format_scanline_unit: u8,
    bitmap_format_scanline_pad: u8,
    min_keycode: u8,
    max_keycode: u8,
    pad_2: u32,
    pub fn format(
        self: @This(),
        writer: *std.Io.Writer,
    ) !void {
        const fields = @typeInfo(@This()).@"struct".fields;
        inline for (fields) |field| {
            const val = @field(self, field.name);
            try writer.print("  .{s} = {any},\n", .{ field.name, val });
        }
    }
};

pub const SetupViewer = struct {
    bytes: []const u8,

    const FixedSize: usize = @sizeOf(SetupReply);
    pub fn setup(self: @This()) *const SetupReply {
        return @ptrCast(@alignCast(self.bytes.ptr));
    }
    pub fn vendor(self: @This()) []const u8 {
        const fixed = self.setup();
        const start: usize = @sizeOf(SetupReply);
        const end = start + fixed.vendor_len;

        return self.bytes[start..end];
    }
    pub fn pixmap_formats(self: @This()) []const FORMAT {
        const fixed = self.setup();
        var start: usize = @sizeOf(SetupReply);
        start += fixed.vendor_len;
        start = std.mem.alignForward(usize, start, 4);
        const end = start + (@sizeOf(FORMAT) * fixed.pixmap_formats_len);

        const ptr: [*]const FORMAT = @ptrCast(@alignCast(self.bytes[start..end].ptr));
        return ptr[0..fixed.pixmap_formats_len];
    }
    pub fn screens(self: @This()) []const SCREEN {
        const fixed = self.setup();
        var start: usize = @sizeOf(SetupReply);
        start += fixed.vendor_len;
        start = std.mem.alignForward(usize, start, 4);
        start += (@sizeOf(FORMAT) * fixed.pixmap_formats_len);
        const end = start + (@sizeOf(SCREEN) * fixed.roots_len);
        const ptr: [*]const SCREEN = @ptrCast(@alignCast(self.bytes[start..end].ptr));
        return ptr[0..fixed.roots_len];
    }
    pub fn format(
        self: @This(),
        writer: *std.Io.Writer,
    ) !void {
        try writer.print("Setup.{{\n", .{});
        try writer.print("{f}", .{self.setup()});
        try writer.print("  .{s} = \"{s}\",\n", .{ "vendor", self.vendor() });
        const format_structs = self.pixmap_formats();
        if (format_structs.len == 0) {
            try writer.print("  .{s} = .{{}},\n", .{"pixmap_formats"});
        } else {
            try writer.print("  .{s} = .{{\n", .{"pixmap_formats"});
            for (format_structs) |format_struct| {
                try writer.print("{f},\n", .{format_struct});
            }
            try writer.print("  }},\n", .{});
        }
        const screen_structs = self.screens();
        if (screen_structs.len == 0) {
            try writer.print("  .{s} = .{{}},\n", .{"screens"});
        } else {
            try writer.print("  .{s} = .{{\n", .{"screens"});
            for (screen_structs) |format_struct| {
                try writer.print("{f},\n", .{format_struct});
            }
            try writer.print("  }},\n", .{});
        }
        try writer.writeAll("}");
    }
};

